// QueryCollections queries the collections edge of a Unit.
func (c *UnitClient) QueryCollections(_m *Unit) *UnitCollectionQuery {
	query := (&UnitCollectionClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(unit.Table, unit.FieldID, id),
			sqlgraph.To(unitcollection.Table, unitcollection.FieldID),
			sqlgraph.Edge(sqlgraph.M2M, false, unit.CollectionsTable, unit.CollectionsPrimaryKey...),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

